  "      // Chrome 111+ 的 /json/new 只接受 PUT，旧版只接受 GET，两者都试。",
  "      const target = await getJson(query, { method: 'PUT' }).catch(() => getJson(query))",
  "      console.log(JSON.stringify({ targetId: target.id }))",
